-- PRIVATE NBA GM DEVELOPMENT FIXTURE. FROZEN 330 ratings and independently assigned
-- overall grades from docs/nba-gm-330-six-skills-PROVISIONAL-2026-10-29.json.
-- Identity crosswalk sourced from docs/nba-gm-official-nba-30-team-roster-crosswalk-2026-10-29.json.
-- PROVISIONAL positions, nullable verified NBA IDs and preserved individual review flags.
-- FICTIONAL game prices (not NBA contracts or guaranteed contract years).
-- Unreleased owner-only experiment; NEVER expose via public gameplay.















do $$
begin
  if (select count(*) from private.nba_gm_dev_players) <> 330
    or (select count(distinct team_code) from private.nba_gm_dev_players) <> 30
    or (select count(*) from private.nba_gm_dev_players where official_nba_player_id is not null) <> 232
    or exists (select 1 from private.nba_gm_dev_players where
      jsonb_typeof(skills) <> 'object'
      or not (skills ?& array['scoring','shooting','playmaking','perimeterDefense','interiorDefense','rebounding'])
      or array_length(positions,1) is null or position_review <> 'unverified'
      or salaries[1] <= 0 or salaries[2] <= 0 or salaries[3] <= 0) then
    raise exception 'NBA GM DEV fixture must retain 330 identities, 30 teams, 232 verified IDs and six skills';
  end if;
end $$;
